state=initial();
const activeRoom = () => state.rooms.find(r=>r.id===state.selected);
const rooms = () => state.rooms.filter(r=>r.company===state.company);
const roomTasks = (r) => state.tasks.filter(t=>t.room===r.id);
const pendingTasks = (r) => roomTasks(r).filter(t=>t.status!=='DONE');
const serviceFor = r => state.services.find(s=>s.room===r.id);
const hasWork = r => r.due || pendingTasks(r).length || serviceFor(r);
function counts(){const rs=rooms();return {WAITING:rs.filter(r=>r.wait>0).length,MINE:rs.filter(r=>r.owner===state.actor||r.dueOwner===state.actor||serviceFor(r)?.assignee===state.actor||pendingTasks(r).some(t=>t.assignee===state.actor)).length,TODAY:rs.filter(hasWork).length,UNASSIGNED:rs.filter(r=>!r.owner).length};}
function filtered(){return rooms().filter(r=>(state.filter==='ALL'||state.filter==='WAITING'&&r.wait>0||state.filter==='MINE'&&(r.owner===state.actor||r.dueOwner===state.actor||serviceFor(r)?.assignee===state.actor||pendingTasks(r).some(t=>t.assignee===state.actor))||state.filter==='TODAY'&&hasWork(r)||state.filter==='UNASSIGNED'&&!r.owner)&&`${r.name} ${r.product}`.toLowerCase().includes(state.query.toLowerCase()));}
const btn = (label,action,cls='',ico='',extra='') => `<button class="${cls}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;
const badge = (text,color='') => `<span class="badge ${color}">${text}</span>`;
const avatar = (r,cls='')=>`<div class="avatar ${cls}">${esc(r.initial)}</div>`;
const dueText = (s)=>s ? `${s.slice(8,10)} ต.ค. · ${s.slice(11,16)} น.` : 'ยังไม่กำหนด';
function say(text){const el=$('#announcement');el.textContent=text;el.classList.add('visible');clearTimeout(say.timer);say.timer=setTimeout(()=>el.classList.remove('visible'),3000);}
function notify(recipient,title,room,target='room'){state.notice.unshift({id:crypto.randomUUID(),recipient,title,room,target,read:false});}
function render(){
 const unread=state.notice.filter(n=>n.recipient===state.actor&&!n.read).length;
 $('#app').innerHTML=`<div class="demo-bar"><span>ต้นแบบ UX/UI <span class="demo-long">· ข้อมูลสมมติ · ไม่มีการส่งข้อความจริง</span></span><div class="row">${btn('วิธีทดลอง','guide')}${btn('เริ่มใหม่','reset')}</div></div>
 <div class="shell"><aside class="sidebar"><div class="brand"><svg class="brand-mark" viewBox="0 0 32 32" aria-hidden="true"><path fill="var(--primary)" d="M5 4h18l-4 12H9l2-8H4Zm6 14h17l-3 11H6l2-4h12l1-3H10Z"/></svg><div><b>BEST<span>CHOICE</span></b><small>WORKSPACE</small></div></div>
 <div><div class="work-label">หมวดงาน</div><div class="work-switch">${btn('งานหน้าร้าน · SHOP','company:SHOP',state.company==='SHOP'?'active':'','shop')}${btn('งานการเงิน · FINANCE','company:FINANCE',state.company==='FINANCE'?'active':'','bank')}</div></div>
 <nav class="nav-group" aria-label="เมนูหลัก">${btn('แชทลูกค้า','page:chat',state.page==='chat'?'active':'','inbox')}${btn('คอมเมนต์','page:comments',state.page==='comments'?'active':'','globe',state.company==='FINANCE'?'disabled title="คอมเมนต์อยู่ในงานหน้าร้าน"':'')}${btn('ภาพรวมทีม','page:report',state.page==='report'?'active':'','chart')}</nav>
 <div class="sidebar-footer"><div class="row">${avatar({initial:staff[state.actor][0]})}<div><strong class="small">${staff[state.actor]}</strong><div class="small muted">${state.actor==='praew'?'ตรวจเครดิต':state.actor==='ton'?'หัวหน้าสาขา':'ฝ่ายขาย'}</div></div></div><label class="small muted" for="actor">ทดลองในมุมของ</label><select id="actor" data-change="actor">${Object.entries(staff).map(([id,name])=>`<option value="${id}" ${state.actor===id?'selected':''}>${name}${id==='may'?' · ฝ่ายขาย':id==='praew'?' · ตรวจเครดิต':' · หัวหน้าสาขา'}</option>`).join('')}</select><p class="tip">ข้อมูลตัวอย่าง 5 ต.ค. 2569<br>ณ เวลา 10:30 น.</p></div></aside>
 <main class="main"><header class="topbar"><div><h1>${state.page==='report'?'ภาพรวมงานแชท':state.page==='comments'?'คอมเมนต์ Facebook':'แชทลูกค้า'}</h1><div class="subtitle">${state.company==='SHOP'?'งานหน้าร้าน · สาขารังสิต':'งานการเงิน · ส่วนกลาง'}</div></div><div class="row"><span class="muted small today">5 ต.ค. 2569 <span class="mono">10:30</span></span><button class="icon-btn notification-button" data-action="notifications" aria-label="การแจ้งเตือน">${icon('bell')}${unread?`<span class="notification-count">${unread}</span>`:''}</button><select class="mobile-only mobile-role" data-change="actor" aria-label="ทดลองในมุมของ">${Object.entries(staff).map(([id,n])=>`<option value="${id}" ${state.actor===id?'selected':''}>ดูเป็น${n}</option>`).join('')}</select></div></header>
 <nav class="mobile-nav" aria-label="เมนูมือถือ"><select class="mobile-work" aria-label="หมวดงาน" data-change="company"><option ${state.company==='SHOP'?'selected':''}>SHOP</option><option ${state.company==='FINANCE'?'selected':''}>FINANCE</option></select>${btn('แชท','page:chat',state.page==='chat'?'active':'')}${btn('คอมเมนต์','page:comments',state.page==='comments'?'active':'','',state.company==='FINANCE'?'disabled':'')}${btn('รายงาน','page:report',state.page==='report'?'active':'')}</nav>
 ${state.page==='chat'?chatPage():state.page==='comments'?commentsPage():reportPage()}</main></div>`;
 const thread=$('.thread');if(thread)thread.scrollTop=thread.scrollHeight;
}
function queue(){const c=counts();return `<section class="queue" aria-label="คิวงาน"><div class="queue-head"><div class="row between"><div class="queue-title">คิวงานวันนี้</div>${badge(`${rooms().length} ลูกค้า`)}</div><div class="search">${icon('search')}<input id="search" aria-label="ค้นหาลูกค้า" placeholder="ค้นหาชื่อ หรือรุ่นที่สนใจ" value="${esc(state.query)}"></div></div><div class="queue-tabs">${[['WAITING','รอตอบ'],['MINE','งานของฉัน'],['TODAY','ถึงนัด / ส่งงาน'],['UNASSIGNED','ไม่มีผู้ดูแล']].map(([key,name])=>btn(`${name}<span>${c[key]}</span>`,`filter:${key}`,state.filter===key?'active':'')).join('')}</div><div class="queue-sort row between"><span>เรียงตามเวลารอ · นานที่สุดก่อน</span>${btn('ทั้งหมด','filter:ALL','btn-quiet btn-small')}</div><div class="room-list">${filtered().map(r=>`<button class="room-item ${state.selected===r.id?'selected':''}" data-action="room:${r.id}"><div class="row">${avatar(r,r.id==='bank'?'blue':'')}<div class="grow"><h3>${esc(r.name)}</h3><span class="channel"><span class="channel-symbol">${r.channel==='LINE'?'L':'f'}</span> ${r.channel}</span></div><span class="mini-status">${r.wait?badge(`${r.wait} นาที`,r.wait>=10?'amber':''):r.closed?badge('ปิดงาน','green'):badge('ตอบแล้ว','green')}</span></div><p class="preview truncate">${esc(r.last)}</p><div class="footer"><span>${r.owner?'ผู้ดูแล '+staff[r.owner]:'ยังไม่มีผู้ดูแล'}</span>${r.due?badge('นัด '+r.due.slice(11,16),'blue'):serviceFor(r)?badge('เรื่องบริการ','blue'):pendingTasks(r).length?badge('มีงานส่งต่อ','amber'):`<span>${esc(r.product.split(' · ')[0])}</span>`}</div></button>`).join('')||`<div class="empty">${icon('check')}<p>${state.query?'ไม่พบลูกค้าที่ค้นหา':'ไม่มีงานในคิวนี้แล้ว'}</p><p class="small">${state.query?'ลองค้นหาด้วยชื่อหรือรุ่นอื่น':'เลือกมุมมองอื่นเพื่อดูงานต่อได้'}</p>${btn('ดูแชททั้งหมด','filter:ALL','btn-quiet')}</div>`}</div></section>`;}
function chatPage(){const r=activeRoom();return `<div class="workspace ${state.mobile?'mobile-chat':''} ${state.details?'show-details':''}">${queue()}<section class="conversation" aria-label="บทสนทนา">${chatHeader(r)}${r.wait?`<div class="wait-banner">${icon('clock')}<strong>ลูกค้ารอ ${r.wait} นาที</strong><span>· เปิดอ่านแล้ว ยังไม่ได้ตอบ</span></div>`:`<div class="wait-banner green">${icon('check')}<span>${r.closed?'ปิดงานสนทนาแล้ว · นัดและงานที่ฝากไว้ยังติดตามต่อได้':'ตอบลูกค้าแล้ว · ติดตามงานถัดไปได้ด้านขวา'}</span></div>`}<div class="thread" aria-label="ประวัติแชท"><div class="date-rule">วันนี้ · 5 ตุลาคม 2569</div>${r.messages.map(message).join('')}${state.notes.filter(n=>n.room===r.id).map(n=>`<div class="internal-note"><strong>${icon('note')} โน้ตภายใน · ลูกค้าไม่เห็น</strong><p>${esc(n.text)}${n.mention?' <b>@'+staff[n.mention]+'</b>':''}</p><p class="small muted">${staff[n.author]} · 10:30</p></div>`).join('')}${roomTasks(r).map(taskCard).join('')}</div>${composer(r)}</section>${details(r)}</div>`;}
function chatHeader(r){return `<header class="chat-head">${btn('','back','btn-quiet icon-btn mobile-only','back','aria-label="กลับไปคิวงาน"')}${avatar(r,'lg')}<div class="grow"><h2>${esc(r.name)}</h2><div class="meta"><span>${r.channel}</span><span>·</span><span>ผู้ดูแล ${r.owner?staff[r.owner]:'ยังไม่มี'}</span></div></div><div class="head-actions">${btn('','details','icon-btn btn-quiet detail-toggle','user','aria-label="ข้อมูลลูกค้าและงานถัดไป"')}${btn(r.closed?'เปิดงาน':'ปิดงาน',r.closed?'reopen':'close-room',r.closed?'':'btn-primary',r.closed?'':'check')}</div></header>`;}
function message(m){return `<div class="msg ${m.type==='out'||m.type==='bot'?'outgoing':''} ${m.type==='bot'?'bot':''}"><div class="bubble">${esc(m.text)}</div><div class="stamp">${m.type==='bot'?icon('spark')+' บอท · ':m.type==='out'?(esc(m.author||'เมย์')+' · '):''}${esc(m.time)}${m.type==='out'?' · ส่งสำเร็จ':''}</div></div>`;}
function taskCard(t){const mine=t.assignee===state.actor;return `<div class="task-card" data-task="${t.id}"><div class="row between"><strong class="small">${icon('users')} งานส่งต่อ</strong>${badge(t.status==='DONE'?'เสร็จแล้ว':t.status==='DOING'?'กำลังทำ':'รอรับงาน',t.status==='DONE'?'green':'amber')}</div><p><b>${esc(t.title)}</b></p><div class="stamp">${staff[t.creator]} ฝากถึง ${staff[t.assignee]} · กำหนด ${dueText(t.due)}</div><div class="task-actions">${t.status==='DONE'?`<span class="small" style="color:var(--primary)">${icon('check')} ${staff[t.assignee]} ทำงานเสร็จแล้ว</span>`:mine?btn(t.status==='TODO'?'รับงานนี้':'เสร็จงานนี้',`task:${t.id}`,t.status==='TODO'?'btn-primary btn-small':'btn-small','check'):`<span class="small muted">รอ${staff[t.assignee]}${t.status==='TODO'?'รับงาน':'ดำเนินการ'}</span>`}<span class="small muted grow" style="text-align:right">ผู้ดูแลแชท ${activeRoom().owner?staff[activeRoom().owner]:'ยังไม่มี'}</span></div></div>`;}
function composer(r){const note=state.mode==='note';return `<div class="composer-wrap"><div class="composer-tabs">${btn('ตอบลูกค้า','mode:reply',!note?'active':'','chat')}${btn('โน้ตภายใน','mode:note',note?'note-active':'','note')}</div>${state.failed&&state.failed.room===r.id?`<div class="send-failed"><span>ส่งไม่สำเร็จ · ลูกค้ายังไม่ได้รับข้อความ</span>${btn('ลองส่งอีกครั้ง','retry','btn-small')}</div>`:''}<form id="composer-form"><div class="composer ${note?'note-mode':''}"><textarea id="draft" aria-label="${note?'เขียนโน้ตภายใน':'ข้อความถึงลูกค้า'}" placeholder="${note?'ฝากข้อมูลให้ทีม · ลูกค้าไม่เห็นข้อความนี้':'พิมพ์ข้อความตอบลูกค้า…'}" required>${esc(state.drafts[r.id+state.mode]||'')}</textarea><div class="composer-bottom"><div class="row">${note?`<select class="mention-select" id="mention" aria-label="แท็กผู้รับโน้ต"><option value="">@ เรียกเพื่อน</option>${Object.entries(staff).filter(([id])=>id!==state.actor).map(([id,n])=>`<option value="${id}">${n}</option>`).join('')}</select>`:`<small>Enter ส่ง · Shift + Enter ขึ้นบรรทัด</small>`}</div><button type="submit" class="btn-primary">${icon(note?'note':'send')}${note?'บันทึกโน้ต':'ส่งข้อความ'}</button></div></div></form></div><div class="simulate">ทดลองต้นแบบ${btn(state.failNext?'ครั้งถัดไปจะส่งล้ม':'จำลองส่งไม่สำเร็จ','fail','btn-small')}<span class="demo-long"> ไม่มีข้อความออกจากหน้านี้</span></div>`;}
function details(r){const task=pendingTasks(r)[0];const service=state.services.find(s=>s.room===r.id);return `<aside class="details" aria-label="ข้อมูลลูกค้า"><div class="details-head"><h3>ข้อมูลลูกค้า</h3>${btn('กลับแชท','details','btn-quiet btn-small detail-toggle','back')}</div><div class="panel next-action"><div class="eyebrow">งานถัดไป</div><h3>${task?esc(task.title):r.due?esc(r.dueTitle):service?'ติดตามเรื่องหลังการขาย':r.wait?'ตอบคำถามลูกค้า':r.closed?'งานสนทนาจบแล้ว':'กำหนดขั้นตอนติดตาม'}</h3><p class="muted">${task?'ผู้รับงาน '+staff[task.assignee]+' · '+dueText(task.due):r.due?`${dueText(r.due)} · ${staff[r.dueOwner||r.owner||'may']}`:service?`${staff[service.assignee]} · ${dueText(service.due)}`:r.wait?'ลูกค้ากำลังรอคำตอบจากพนักงาน':'ตั้งนัดหรือฝากงานให้ทีมทำต่อได้'}</p><div class="row actions">${btn('ตั้งนัด','schedule','','calendar')}${btn('ส่งงาน','handoff','','users')}</div></div><div class="panel"><div class="row between"><h3>สถานะการขาย</h3>${badge(r.stage===5?'ซื้อแล้ว':r.stage===4?'ตรวจเครดิต':'สนใจสินค้า',r.stage===5?'green':'')}</div><div class="progress-steps">${[1,2,3,4,5].map(n=>`<span class="${n<=r.stage?'done':''}"></span>`).join('')}</div><div class="step-labels"><span>เริ่มคุย</span><span>รู้ตัวตน</span><span>สนใจ</span><span>เครดิต</span><span>ซื้อแล้ว</span></div><div class="divider"></div><div class="label">${state.company==='FINANCE'?'สัญญาที่เกี่ยวข้อง':'สินค้าที่สนใจ'}</div><p><strong>${esc(r.product)}</strong></p><p class="tip">อัปเดตจากข้อมูลและเอกสารในระบบ</p></div><div class="panel"><div class="row between"><h3>${esc(r.name.split(' · ')[0])}</h3>${badge('ลูกค้าเดิม')}</div><dl class="key-values"><dt>เบอร์ติดต่อ</dt><dd>${esc(r.phone)}</dd><dt>ผู้ดูแลแชท</dt><dd>${r.owner?staff[r.owner]:'ยังไม่มีผู้ดูแล'}</dd><dt>ช่องทาง</dt><dd>${r.channel}</dd><dt>สาขา</dt><dd>${state.company==='SHOP'?'รังสิต':'ส่วนกลาง'}</dd></dl></div><div class="section-label">ข้อมูลที่เกี่ยวข้อง</div><div class="panel" style="padding-top:0;padding-bottom:0">${btn(`<span class="row">${icon('shield')}เครดิตและข้อเสนอ</span>${icon('chevron')}`,'credit','context-action')}${btn(`<span class="row">${icon('note')}สัญญาและการชำระ</span>${icon('chevron')}`,'contract','context-action')}${btn(`<span class="row">${icon('wrench')}หลังการขาย ${service?'· 1':''}</span>${icon('chevron')}`,'service','context-action')}</div>${service?`<div class="panel"><div class="row between"><strong class="small">${service.case?'เคส '+service.case:'รับเรื่องหลังการขาย'}</strong>${badge(service.case?'ผูกเคสแล้ว':'รับเรื่องแล้ว',service.case?'green':'amber')}</div><p style="margin-top:9px">${esc(service.symptom)}</p><p class="tip">${service.case?'สถานะจากเคส: อยู่ระหว่างตรวจสอบ':'ยังไม่ใช่การรับฝากเครื่อง'}</p>${btn(service.case?'ดูเคสตัวอย่าง':'ผูกเคสเดิม',service.case?'case-detail':'link-case','btn-small full','',`style="margin-top:10px"`)}</div>`:''}</aside>`;}
function commentsPage(){const c=state.comments.find(x=>x.id===state.commentSelected);return `<div class="workspace comment-workspace ${state.mobile?'mobile-chat':''}"><section class="queue"><div class="queue-head"><div class="row between"><h2>คอมเมนต์ที่ต้องดูแล</h2>${badge(state.comments.filter(x=>x.status==='OPEN').length+' รอตอบ','amber')}</div><p class="small muted" style="margin-top:7px">Facebook · BESTCHOICE รังสิต</p></div><div class="queue-sort">เรียงตามเวลารอ · รวมทุกโพสต์</div><div class="room-list">${state.comments.map(x=>`<button class="room-item ${x.id===c.id?'selected':''}" data-action="comment:${x.id}"><div class="row">${avatar(x,'blue')}<h3 class="grow">${esc(x.name)}</h3>${badge(x.status==='OPEN'?x.wait+' นาที':'ตอบแล้ว',x.status==='OPEN'?'amber':'green')}</div><p class="preview">${esc(x.text)}</p><div class="footer"><span>${x.owner?'ผู้ดูแล '+staff[x.owner]:'ยังไม่มีผู้ดูแล'}</span><span>${x.time}</span></div></button>`).join('')}</div></section><section class="conversation"><header class="chat-head">${btn('','back','btn-quiet icon-btn mobile-only','back','aria-label="กลับไปคิวคอมเมนต์"')}${avatar(c,'blue lg')}<div class="grow"><h2>${esc(c.name)}</h2><div class="meta">คอมเมนต์บนโพสต์ · ยังไม่ผูกข้อมูลลูกค้า</div></div>${badge('สาธารณะ','blue')}</header><div class="public-banner">${icon('globe')}ทุกคนที่เห็นโพสต์อ่านคำตอบนี้ได้ · ไม่ส่งข้อมูลส่วนตัวของลูกค้า</div><div class="comment-post"><div class="row"><div class="post-visual">${icon('phone')}</div><div class="grow"><div class="small muted">โพสต์ต้นทาง · BESTCHOICE</div><h3>${esc(c.post)}</h3><p class="small muted">โพสต์ตัวอย่าง · 5 ต.ค. 2569</p></div></div></div><div class="thread comment-thread"><div class="msg"><div class="small muted">${esc(c.name)}</div><div class="bubble">${esc(c.text)}</div><div class="stamp">${c.time} · คอมเมนต์สาธารณะ</div></div>${c.replies.map(m=>`<div class="msg outgoing"><div class="bubble">${esc(m.text)}</div><div class="stamp">${esc(m.name)} · ตอบในนาม BESTCHOICE · ส่งสำเร็จ (จำลอง)</div></div>`).join('')}</div><div class="composer-wrap comment-composer"><form id="public-form"><div class="composer"><textarea id="public-draft" aria-label="คำตอบสาธารณะ" placeholder="พิมพ์คำตอบบนโพสต์นี้…" required></textarea><div class="composer-bottom"><span class="small muted">${icon('globe')} ตอบในนาม BESTCHOICE</span><button type="submit" class="btn-primary">${icon('send')}ตอบสาธารณะ</button></div></div></form><p class="tip">การทักส่วนตัวยังไม่เปิดในต้นแบบนี้ ต้องตรวจสิทธิ์ Meta ก่อนใช้งานจริง</p></div></section></div>`;}
function reportPage(){const waiting=rooms().filter(r=>r.wait>0),due=rooms().filter(r=>r.due).length;return `<div class="report"><div class="report-head"><div><h2>วันนี้ ทีมควรจัดการอะไรก่อน</h2><p>5 ตุลาคม 2569 · ณ เวลา 10:30 น. · ${state.company==='SHOP'?'งานหน้าร้าน':'งานการเงิน'}</p></div>${badge('ข้อมูลจำลอง','blue')}</div><div class="stat-grid"><button class="stat urgent" data-action="report-wait"><p>ลูกค้ารอคำตอบจากคน</p><div class="number">${waiting.length}<span class="small"> คน</span></div><small>${waiting.filter(r=>r.wait>=10).length} คนรอเกิน 10 นาที · กดดูคิว ${icon('arrow')}</small></button><button class="stat" data-action="report-due"><p>นัดติดตามวันนี้</p><div class="number">${due}<span class="small"> นัด</span></div><small>กดดูงานที่ต้องติดต่อกลับ ${icon('arrow')}</small></button><div class="stat"><p>เวลารอคำตอบจากคน</p><div class="number">6<span class="small"> นาที</span></div><small>ค่ามัธยฐาน · ตัวอย่าง 4 รอบ · ไม่รวมบอท</small></div><div class="stat"><p>บอทตอบครั้งแรก</p><div class="number">1<span class="small"> นาที</span></div><small>ค่ามัธยฐาน · ตัวอย่าง 3 รอบ</small></div></div><div class="report-grid"><section class="report-panel"><header><h3>การตอบและงานของทีม</h3><small class="muted">ผู้ตอบจริงแยกจากผู้ดูแลแชทและเจ้าของยอดขาย</small></header><table><thead><tr><th>พนักงาน</th><th>ตอบสำเร็จ</th><th>รับงาน</th><th>เสร็จงาน</th></tr></thead><tbody>${Object.entries(staff).map(([id,n],i)=>`<tr><td><div class="row">${avatar({initial:n[0]})}<strong>${n}</strong></div></td><td class="mono">${[2,1,1][i]+state.rooms.filter(r=>r.company===state.company).flatMap(r=>r.messages).filter(m=>m.simulated&&m.actor===id).length}</td><td class="mono">${state.tasks.filter(t=>t.assignee===id&&t.status!=='TODO'&&rooms().some(r=>r.id===t.room)).length}</td><td class="mono">${state.tasks.filter(t=>t.assignee===id&&t.status==='DONE'&&rooms().some(r=>r.id===t.room)).length}</td></tr>`).join('')}<tr><td class="muted">ไม่ทราบผู้ตอบ</td><td class="mono">1</td><td>—</td><td>—</td></tr></tbody></table><div class="report-foot">คำตอบจากช่องทางที่ระบุตัวพนักงานไม่ได้ แสดงแยก ไม่ยกให้ผู้ดูแลแชท</div></section><section class="report-panel"><header><h3>ลูกค้าอยู่ขั้นไหน</h3><small class="muted">สถานะปัจจุบันของลูกค้าในชุดตัวอย่าง</small></header><div class="funnel">${['เริ่มคุย','รู้ตัวตน','สนใจสินค้า','ตรวจเครดิต','ซื้อแล้ว'].map((label,i)=>{const n=rooms().filter(r=>r.stage>=i+1).length;return `<div class="funnel-row"><span>${label}</span><div class="track"><div style="width:${n/rooms().length*100}%"></div></div><b class="mono">${n}</b></div>`}).join('')}</div><div class="report-foot">แต่ละขั้นอิงหลักฐาน · ลูกค้าซื้อเงินสดอาจข้ามขั้นตรวจเครดิต</div></section></div>${state.company==='SHOP'?`<section class="panel" style="margin-top:18px"><div class="row between wrap"><div><h3>ยอดขายที่เชื่อมโยงกับแชท</h3><p class="muted">ตัวอย่าง 1 รายการ · นับรายการขายครั้งเดียว แม้มีหลายห้องแชท</p></div><strong class="mono" style="font-size:24px">฿ 16,900</strong></div><div class="divider"></div><p class="small muted">เจ้าของยอดขาย: ต้น · ผู้ตอบและผู้รับงานอาจเป็นคนอื่น · ไม่รวมค่างวดรับชำระเป็นยอดขายซ้ำ</p></section>`:''}<div class="coverage">${icon('info')}<span>ตัวเลขสำหรับรีวิวหน้าจอเท่านั้น · เมตริกเวลาและยอดขายเป็นชุดตัวอย่างคงที่ ส่วนคิว นัด และงานที่ทดลองจะเปลี่ยนตามการกดใช้งาน · ระบบจริงต้องแสดงช่วงเก็บข้อมูลและรายการที่ยังระบุผู้ตอบไม่ได้</span></div></div>`;}
function dialog(title,body,footer='',form=''){const d=$('#dialog');d.innerHTML=`${form?`<form id="${form}">`:''}<div class="dialog-head"><h2 id="dialog-title">${title}</h2>${btn('','dismiss','btn-quiet icon-btn','close','type="button" aria-label="ปิดหน้าต่าง"')}</div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-foot">${footer}</div>`:''}${form?'</form>':''}`;d.showModal();}
const cancel = ()=>btn('ยกเลิก','dismiss','','','type="button"');
const submit = text=>`<button type="submit" class="btn-primary">${text}</button>`;
const peopleOptions = selected=>Object.entries(staff).map(([id,n])=>`<option value="${id}" ${id===selected?'selected':''}>${n}${id==='praew'?' · ตรวจเครดิต':id==='ton'?' · หัวหน้าสาขา':' · ฝ่ายขาย'}</option>`).join('');
function openSchedule(){const r=activeRoom();dialog('ตั้งนัดติดตาม',`<p class="hint">${esc(r.name)} · นัดนี้อยู่กับแชทเดิม</p><label>งานที่ต้องทำ<input name="title" required maxlength="150" value="${esc(r.dueTitle||'ติดตามเอกสารและแจ้งขั้นตอนถัดไป')}" autofocus></label><label>วันและเวลา · กรุงเทพฯ<input type="datetime-local" name="due" value="${r.due||'2026-10-05T14:30'}" required></label><label>ผู้รับผิดชอบ<select name="assignee">${peopleOptions(state.actor)}</select></label>`,cancel()+submit('บันทึกนัด'),'schedule-form');}
function openHandoff(){const r=activeRoom();dialog('ส่งงานให้ทีม',`<p class="hint">ผู้ดูแลแชทยังคงเป็น ${r.owner?staff[r.owner]:'ยังไม่มีผู้ดูแล'} · การฝากงานไม่โอนยอดขาย</p><label>ให้ช่วยทำอะไร<input name="title" required maxlength="150" placeholder="เช่น ตรวจเอกสารเครดิตของคุณมุก" autofocus></label><label>ผู้รับงาน<select name="assignee">${peopleOptions(state.actor==='praew'?'may':'praew')}</select></label><label>กำหนดเสร็จ · กรุงเทพฯ<input type="datetime-local" name="due" value="2026-10-05T11:30" required></label>`,cancel()+submit('ส่งงาน'),'handoff-form');}
function openService(){const r=activeRoom(),s=state.services.find(x=>x.room===r.id);if(s){if(s.case)caseDetail();else openLinkCase();return;}dialog('รับเรื่องหลังการขาย',`<div class="notice">บันทึกปัญหาจากแชท ยังไม่ใช่การรับฝากเครื่องหรือเปิดใบซ่อม</div><label>อาการที่ลูกค้าแจ้ง<textarea name="symptom" required minlength="5" placeholder="อธิบายอาการและสิ่งที่ต้องติดตาม" autofocus>${r.id==='keng'?'ชาร์จไม่เข้า ต้องการให้สาขาตรวจสอบ':''}</textarea></label><label>เครื่องที่เกี่ยวข้อง<select name="device"><option>${esc(r.product)}</option><option>ยังไม่ทราบเครื่อง — ตรวจสอบกับลูกค้าก่อน</option></select></label><label>ผู้ติดตามเรื่อง<select name="assignee">${peopleOptions('ton')}</select></label><label>นัดติดตาม · กรุงเทพฯ<input type="datetime-local" name="due" value="2026-10-05T15:00" required></label>`,cancel()+submit('บันทึกรับเรื่อง'),'service-form');}
function openLinkCase(){const r=activeRoom(),s=state.services.find(x=>x.room===r.id);if(!s)return;if(r.id!=='keng'||s.device.startsWith('ยังไม่ทราบ')){dialog('ยังไม่พบเคสที่ตรงกัน',`<p class="small">ต้องตรวจสอบลูกค้าและเครื่องก่อนผูกเคส เพื่อไม่ให้ประวัติของคนละเครื่องปนกัน</p><p class="hint" style="margin-top:12px">ตัวอย่างเคสที่ผูกได้อยู่ในแชทคุณเก่ง · iPhone 13</p>`,btn('กลับไปแชท','dismiss','btn-primary'));return;}dialog('ผูกกับเคสหลังการขาย',`<p class="hint">ตัวอย่างเคสของลูกค้าคนนี้ · การผูกเคสไม่ส่งข้อความรับเครื่องซ้ำ</p><div class="panel"><span class="badge green">ลูกค้าและเครื่องตรงกัน · ข้อมูลสมมติ</span><h3 style="margin-top:12px">AS-20261005-002</h3><p>${esc(r.name)} · ${esc(s.device)}</p><p class="muted">อยู่ระหว่างตรวจสอบ · สาขารังสิต</p></div><p class="small muted">ระบบจริงจะแสดงเฉพาะเคสที่ตรวจสิทธิ์และข้อมูลตรงกัน หากยังไม่รับฝากเครื่องให้เปิดเคสผ่านขั้นตอนเดิม</p>`,cancel()+btn('ผูกเคสนี้','confirm-link','btn-primary'));}
function caseDetail(){const r=activeRoom();dialog('เคส AS-20261005-002',`<span class="badge green">เคสหลังการขายตัวอย่าง</span><h3 style="margin:14px 0 6px">${esc(r.name)}</h3><p class="small">${esc(r.product)}</p><div class="divider"></div><dl class="key-values"><dt>สถานะเคส</dt><dd>อยู่ระหว่างตรวจสอบ</dd><dt>ผู้ดูแล</dt><dd>ต้น · สาขารังสิต</dd><dt>งานถัดไป</dt><dd>แจ้งผลตรวจให้ลูกค้าทราบ</dd></dl><p class="hint" style="margin-top:18px">หน้าจอนี้แสดงรายละเอียดตัวอย่าง การเปลี่ยนสถานะซ่อมและเอกสารรับฝากจะทำในระบบหลังการขายเดิม</p>`,btn('กลับไปแชท','dismiss','btn-primary'));}
function notifications(){const ns=state.notice.filter(n=>n.recipient===state.actor);dialog(`การแจ้งเตือนของ${staff[state.actor]}`,`<div class="notification-list">${ns.map(n=>`<button class="${n.read?'':'unread'}" data-action="notice:${n.id}">${esc(n.title)}<small>${n.read?'เปิดอ่านแล้ว':'ยังไม่อ่าน'} · 10:30 · กดไปที่งาน</small></button>`).join('')||'<div class="empty">ยังไม่มีการแจ้งเตือน<br><span class="small">ลองส่งงานหรือ Mention ถึงคนนี้ก่อน</span></div>'}</div><p class="tip">เปิดอ่านการแจ้งเตือนไม่ถือว่ารับงานหรือทำงานเสร็จ</p>`);}
function changeCompany(value){state.company=value;state.selected=rooms()[0].id;state.filter='WAITING';state.query='';state.mobile=false;state.details=false;if(value==='FINANCE'&&state.page==='comments')state.page='chat';render();}
function sendReply(text){const r=activeRoom();if(state.failNext){state.failNext=false;state.failed={room:r.id,text};render();say('จำลองส่งล้ม · ข้อความยังไม่ถึงลูกค้า');return;}r.messages.push({type:'out',text,time:'10:30',author:staff[state.actor],actor:state.actor,simulated:true});r.wait=0;r.closed=false;if(!r.owner)r.owner=state.actor;r.last=text;state.drafts[r.id+'reply']='';state.failed=null;state.humanReplies++;render();say('ส่งข้อความแล้ว · ออกจากคิวรอตอบ');}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const [action,...parts]=b.dataset.action.split(':');const value=parts.join(':');const r=activeRoom();
 if(action==='company'){changeCompany(value);return;}
 if(action==='page'){state.page=value;state.mobile=false;state.details=false;render();return;}
 if(action==='filter'){state.filter=value;render();return;}
 if(action==='room'){state.selected=value;state.mobile=true;state.details=false;state.mode='reply';state.failed=null;render();return;}
 if(action==='back'){state.mobile=false;state.details=false;render();return;}
 if(action==='details'){state.details=!state.details;render();return;}
 if(action==='mode'){state.mode=value;render();$('#draft')?.focus();return;}
 if(action==='schedule'){openSchedule();return;}
 if(action==='handoff'){openHandoff();return;}
 if(action==='service'){openService();return;}
 if(action==='link-case'){openLinkCase();return;}
 if(action==='case-detail'){caseDetail();return;}
 if(action==='confirm-link'){const s=state.services.find(x=>x.room===r.id);s.case='AS-20261005-002';$('#dialog').close();render();say('ผูกเคสแล้ว · สถานะแสดงจากเคสหลังการขาย');return;}
 if(action==='dismiss'){$('#dialog').close();return;}
 if(action==='notifications'){notifications();return;}
 if(action==='notice'){const n=state.notice.find(x=>x.id===value&&x.recipient===state.actor);if(!n)return;n.read=true;state.selected=n.room;state.company=activeRoom().company;state.page='chat';state.mobile=true;state.details=false;$('#dialog').close();render();return;}
 if(action==='task'){const t=state.tasks.find(x=>x.id===value);if(t.assignee!==state.actor||t.status==='DONE')return;t.status=t.status==='TODO'?'DOING':'DONE';notify(t.creator,`${staff[state.actor]}${t.status==='DONE'?'ทำเสร็จแล้ว':'รับงานแล้ว'}: ${t.title}`,t.room,'task');render();say(t.status==='DONE'?'บันทึกว่างานเสร็จแล้ว':'รับงานแล้ว · ผู้ดูแลแชทไม่เปลี่ยน');return;}
 if(action==='close-room'){if(hasWork(r)){dialog('ปิดงานสนทนา',`<p class="small">แชทนี้ยังมีนัดหรืองานที่ฝากทีมไว้ การปิดสนทนาจะหยุดคิวรอตอบ แต่ยังเก็บงานเหล่านั้นให้ติดตามต่อ</p>`,cancel()+btn('ปิดเฉพาะสนทนา','confirm-close','btn-primary'));}else{r.closed=true;r.wait=0;render();say('ปิดงานสนทนาแล้ว');}return;}
 if(action==='confirm-close'){r.closed=true;r.wait=0;$('#dialog').close();render();say('ปิดสนทนาแล้ว · งานติดตามยังอยู่');return;}
 if(action==='reopen'){r.closed=false;render();say('เปิดงานสนทนาแล้ว');return;}
 if(action==='fail'){state.failNext=!state.failNext;render();return;}
 if(action==='retry'){if(state.failed&&state.failed.room===r.id)sendReply(state.failed.text);return;}
 if(action==='comment'){state.commentSelected=value;state.mobile=true;render();return;}
 if(action==='report-wait'||action==='report-due'){state.page='chat';state.filter=action==='report-wait'?'WAITING':'TODAY';state.mobile=false;state.details=false;render();return;}
 if(action==='credit'){dialog('เครดิตและข้อเสนอ',`<div class="notice">รายละเอียดตัวอย่าง · ไม่มีการยื่นเครดิตจริง</div><p class="small">${esc(r.name)} · ${esc(r.product)}</p><div class="divider"></div><p class="small">${r.stage===4?'ได้รับเอกสารแล้ว · อยู่ระหว่างตรวจเครดิต':r.stage===5?'ลูกค้ามีรายการซื้อแล้ว':'ยังไม่ได้ยื่นตรวจเครดิต'}</p><p class="hint" style="margin-top:12px">ระบบจริงใช้แผงตรวจเครดิตและเตรียมข้อเสนอเดิม ไม่เพิ่มขั้นเปลี่ยนสถานะอนุมัติด้วยมือ</p>`,btn('กลับไปแชท','dismiss','btn-primary'));return;}
 if(action==='contract'){dialog('สัญญาและการชำระ',`<p class="small">${r.stage===5?'มีรายการซื้อที่เชื่อมกับลูกค้าคนนี้':'ยังไม่มีสัญญาที่เชื่อมกับลูกค้าคนนี้'}</p><p class="hint" style="margin-top:12px">รายละเอียดและสิทธิ์การเข้าถึงใช้แผงสัญญาเดิมของ BESTCHOICE · ไม่มีข้อมูลทางการเงินจริงในต้นแบบ</p>`,btn('กลับไปแชท','dismiss','btn-primary'));return;}
 if(action==='reset'){state=initial();$('#dialog').close();render();say('เริ่มข้อมูลตัวอย่างใหม่แล้ว');return;}
 if(action==='guide'){dialog('ลองทำงานครบหนึ่งรอบ',`<div class="guide-steps"><div class="guide-step"><div><strong>ตอบคุณมุก</strong><p>เปิดอ่านแล้วจะยังรออยู่ ลองส่งล้มและกดส่งใหม่</p></div></div><div class="guide-step"><div><strong>ตั้งนัดและส่งงานให้แพรว</strong><p>เปิดข้อมูลลูกค้า → ตั้งนัด / ส่งงาน ผู้ดูแลแชทยังเป็นเมย์</p></div></div><div class="guide-step"><div><strong>เปลี่ยนเป็นแพรวเพื่อรับงาน</strong><p>เลือก “ทดลองในมุมของ” → เปิดแจ้งเตือน → รับงาน → เสร็จงาน</p></div></div><div class="guide-step"><div><strong>ลองคอมเมนต์และหลังการขาย</strong><p>ตอบสาธารณะในเมนูคอมเมนต์ หรือเปิดข้อมูลคุณเก่งเพื่อรับเรื่องหลังการขาย</p></div></div><div class="guide-step"><div><strong>เปิดภาพรวมทีม</strong><p>กดตัวเลขแชทค้างกลับไปที่คิวได้ รีโหลดหรือเริ่มใหม่เพื่อล้างข้อมูล</p></div></div></div><div class="notice">ทุกข้อมูลเป็นตัวอย่าง ไม่มีการส่งข้อความ ยื่นเครดิต หรือบันทึกข้อมูลลูกค้าจริง</div>`,btn('เริ่มทดลอง','dismiss','btn-primary'));}
});
document.addEventListener('change',e=>{if(e.target.dataset.change==='actor'){state.actor=e.target.value;render();say('กำลังทดลองในมุมของ'+staff[state.actor]);}if(e.target.dataset.change==='company')changeCompany(e.target.value);});
document.addEventListener('input',e=>{if(e.target.id==='search'){state.query=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);}if(e.target.id==='draft')state.drafts[state.selected+state.mode]=e.target.value;});
document.addEventListener('keydown',e=>{if(e.target.id==='draft'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('#composer-form').requestSubmit();}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target;const fd=new FormData(form);const r=activeRoom();
 if(form.id==='composer-form'){const text=$('#draft').value.trim();if(!text)return;if(state.mode==='reply'){sendReply(text);}else{const mention=$('#mention').value;state.notes.push({room:r.id,text,mention,author:state.actor});if(mention)notify(mention,`${staff[state.actor]}เรียกคุณในโน้ต: ${text}`,r.id,'note');state.drafts[r.id+'note']='';render();say('บันทึกโน้ตแล้ว · ลูกค้าไม่เห็นข้อความนี้');}return;}
 if(form.id==='schedule-form'){r.due=String(fd.get('due'));r.dueTitle=String(fd.get('title')).trim();r.dueOwner=String(fd.get('assignee'));notify(r.dueOwner,`นัดติดตาม ${r.name}: ${r.dueTitle}`,r.id);$('#dialog').close();render();say('บันทึกนัดแล้ว · ดูได้ในคิวถึงนัด / ส่งงาน');return;}
 if(form.id==='handoff-form'){const t={id:crypto.randomUUID(),room:r.id,title:String(fd.get('title')).trim(),assignee:String(fd.get('assignee')),due:String(fd.get('due')),creator:state.actor,status:'TODO'};state.tasks.push(t);notify(t.assignee,`${staff[state.actor]}ฝากงาน: ${t.title}`,r.id,'task');$('#dialog').close();render();say('ส่งงานให้'+staff[t.assignee]+'แล้ว');return;}
 if(form.id==='service-form'){state.services.push({id:crypto.randomUUID(),room:r.id,symptom:String(fd.get('symptom')).trim(),device:String(fd.get('device')),assignee:String(fd.get('assignee')),due:String(fd.get('due')),case:null});notify(String(fd.get('assignee')),`รับเรื่องหลังการขาย: ${r.name}`,r.id,'service');$('#dialog').close();state.details=true;render();say('รับเรื่องแล้ว · ยังไม่ใช่การรับฝากเครื่อง');return;}
 if(form.id==='public-form'){const text=$('#public-draft').value.trim();if(!text)return;const c=state.comments.find(x=>x.id===state.commentSelected);c.replies.push({text,name:staff[state.actor]});c.status='RESPONDED';c.owner=c.owner||state.actor;render();say('บันทึกคำตอบสาธารณะแล้ว (จำลอง)');}
});
render();
